const PRICING = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Pricing | Faith Vision Media</title><meta name=\"robots\" content=\"noindex, nofollow\"><meta name=\"theme-color\" content=\"#0B0B0A\"><meta name=\"color-scheme\" content=\"dark\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin><link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Geist:wght@400..700&display=swap\"><style>\n:root{--black:#0B0B0A;--black-2:#151513;--line:#2A2925;--cream:#EDE4D3;--cream-dim:#A39B8C;--gold:#B8935A;--font:'Geist',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;--gutter:clamp(16px,4vw,48px);color-scheme:dark}\n*,*::before,*::after{box-sizing:border-box}\nhtml{background:var(--black);-webkit-text-size-adjust:100%}\nbody{margin:0;background:var(--black);color:var(--cream);font-family:var(--font);font-size:1.0625rem;line-height:1.6;-webkit-font-smoothing:antialiased}\na{color:inherit;text-decoration:none}\nh1,h2,h3,p,ul{margin:0}ul{padding:0;list-style:none}\n:focus-visible{outline:2px solid var(--gold);outline-offset:3px}\n.wrap{max-width:1180px;margin-inline:auto;padding-inline:var(--gutter)}\n.top{display:flex;align-items:center;justify-content:space-between;height:76px;border-bottom:1px solid var(--line)}\n.logo{font-weight:700;letter-spacing:-.02em}\n.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:14px 26px;background:var(--cream);color:var(--black);border:1px solid var(--cream);font-weight:600;font-size:.9375rem;line-height:1;white-space:nowrap;transition:background .2s,color .2s}\n.btn:hover{background:transparent;color:var(--cream)}\n.btn--ghost{background:transparent;color:var(--cream);border-color:var(--line)}\n.btn--ghost:hover{border-color:var(--cream)}\n.hero{padding-block:clamp(56px,9vw,120px) clamp(40px,6vw,72px)}\n.eyebrow{color:var(--gold);font-size:.8125rem;font-weight:600;letter-spacing:.14em;text-transform:uppercase;margin-bottom:18px}\nh1{font-size:clamp(2.75rem,8vw,6.5rem);line-height:.95;letter-spacing:-.045em;font-weight:700}\n.lead{color:var(--cream-dim);font-size:1.2rem;max-width:40ch;margin-top:22px}\n.sec{padding-block:clamp(40px,6vw,72px);border-top:1px solid var(--line)}\nh2{font-size:clamp(1.75rem,3.4vw,2.6rem);letter-spacing:-.03em;line-height:1.05;margin-bottom:clamp(24px,3vw,40px)}\n.grid{display:grid;gap:1px;background:var(--line);border:1px solid var(--line);grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr))}\n.card{background:var(--black);padding:clamp(22px,3vw,34px);display:flex;flex-direction:column;gap:14px}\n.card--hot{background:var(--black-2)}\n.tag{align-self:flex-start;font-size:.75rem;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--black);background:var(--gold);padding:5px 9px}\n.card h3{font-size:1.35rem;font-weight:600;letter-spacing:-.02em;line-height:1.2}\n.price{font-size:2.6rem;font-weight:700;letter-spacing:-.04em;line-height:1}\n.price small{font-size:.95rem;font-weight:500;color:var(--cream-dim);letter-spacing:0;margin-left:4px}\n.card ul{display:grid;gap:8px;color:var(--cream-dim);font-size:.975rem}\n.card li{padding-left:18px;position:relative}\n.card li::before{content:\"\";position:absolute;left:0;top:.7em;width:7px;height:1px;background:var(--gold)}\n.meta{margin-top:auto;padding-top:12px;border-top:1px solid var(--line);font-size:.875rem;color:var(--cream-dim)}\n.sizes{display:grid;gap:10px}\n.size{display:flex;justify-content:space-between;align-items:baseline;gap:12px;font-size:1rem}\n.size b{font-size:1.6rem;letter-spacing:-.03em}\n.list{border-top:1px solid var(--line)}\n.row{display:flex;justify-content:space-between;align-items:baseline;gap:16px;padding:18px 0;border-bottom:1px solid var(--line)}\n.row span{color:var(--cream-dim);font-size:.9rem;display:block}\n.row b{font-size:1.35rem;letter-spacing:-.02em;white-space:nowrap}\n.row b small{font-size:.85rem;font-weight:500;color:var(--cream-dim)}\n.cta{padding-block:clamp(56px,8vw,110px);border-top:1px solid var(--line);text-align:center}\n.cta p{color:var(--cream-dim);margin:14px auto 28px;max-width:44ch}\n.cta .acts{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}\nfooter{border-top:1px solid var(--line);padding-block:28px;color:var(--cream-dim);font-size:.875rem}\n</style></head><body>\n<header class=\"wrap top\"><a class=\"logo\" href=\"/\">Faith Vision Media</a><a class=\"btn\" href=\"/book\">Book a shoot</a></header>\n<main>\n<section class=\"wrap hero\"><p class=\"eyebrow\">Private rate sheet</p><h1>Pricing</h1><p class=\"lead\">Real estate photo, video and drone in Buffalo, NY. Every shoot includes MLS-ready delivery.</p></section>\n\n<section class=\"wrap sec\"><h2>Bundles</h2><div class=\"grid\">\n<article class=\"card card--hot\"><span class=\"tag\">Most popular</span><h3>Standard Bundle</h3><p class=\"price\">$275</p><ul><li>Photos, any square footage (35 photos)</li><li>Social reel</li><li>Script and direction</li></ul><p class=\"meta\">Delivered in 2&ndash;3 days</p></article>\n<article class=\"card\"><h3>Premium Bundle</h3><p class=\"price\">$400</p><ul><li>Photos, 2,700+ sq ft (50 photos)</li><li>Cinematic video</li><li>Social reel</li></ul><p class=\"meta\">Delivered in 3&ndash;5 days</p></article>\n</div></section>\n\n<section class=\"wrap sec\"><h2>Photos</h2><div class=\"grid\">\n<article class=\"card\"><h3>HDR photos</h3><div class=\"sizes\"><p class=\"size\">Under 2,700 sq ft <b>$150</b></p><p class=\"size\">Over 2,700 sq ft <b>$200</b></p></div><ul><li>MLS-ready stills</li><li>Priced by square footage</li></ul><p class=\"meta\">Delivered in 24 hours</p></article>\n</div></section>\n\n<section class=\"wrap sec\"><h2>Video</h2><div class=\"grid\">\n<article class=\"card\"><h3>Non-stop walk-through reel</h3><p class=\"price\">$120</p><ul><li>One continuous walk-through</li><li>Stabilized with basic edits</li><li>Shows the full layout clearly</li><li>Script</li></ul><p class=\"meta\">Delivered in 2&ndash;3 days</p></article>\n<article class=\"card\"><h3>Social reel (vertical)</h3><p class=\"price\">$190</p><ul><li>30&ndash;45 second video</li><li>Fast cuts and music</li><li>Made for Instagram and TikTok</li><li>Script and direction</li></ul><p class=\"meta\">Delivered in 2&ndash;3 days</p></article>\n<article class=\"card\"><h3>Cinematic reel (horizontal)</h3><p class=\"price\">$260</p><ul><li>45&ndash;90 second edited video</li><li>Smooth shots and music</li><li>Great for standout listings</li></ul><p class=\"meta\">Delivered in 2&ndash;3 days</p></article>\n</div></section>\n\n<section class=\"wrap sec\"><h2>For businesses</h2><div class=\"grid\">\n<article class=\"card card--hot\"><h3>Branding video</h3><p style=\"color:var(--cream-dim);font-size:.95rem;margin-top:-6px\">For agents, small businesses, restaurants and more</p><p class=\"price\">$300</p><ul><li>Discovery call to learn your business and goals</li><li>Script written for you</li><li>Up to 3 hours on site</li><li>A second location included if you have one</li><li>Vertical video for Instagram, TikTok and Reels</li><li>Horizontal video for your website, YouTube and ads</li><li>Your logo and contact info at the end of the video</li><li>1 round of revisions</li></ul><p class=\"meta\">Delivered in 3&ndash;5 days</p></article>\n</div></section>\n\n<section class=\"wrap sec\"><h2>Add-ons</h2><div class=\"list\">\n<p class=\"row\"><span><strong style=\"color:var(--cream);font-size:1.0625rem;display:block\">Drone photo / video</strong></span><b>$90</b></p>\n<p class=\"row\"><span><strong style=\"color:var(--cream);font-size:1.0625rem;display:block\">Day to night</strong>Real daylight to dusk, captured on site and blended into one cinematic clip</span><b>$75</b></p>\n<p class=\"row\"><span><strong style=\"color:var(--cream);font-size:1.0625rem;display:block\">Next-day delivery (video)</strong></span><b>$30</b></p>\n<p class=\"row\"><span><strong style=\"color:var(--cream);font-size:1.0625rem;display:block\">Twilight photo</strong></span><b>$25 <small>/ photo</small></b></p>\n<p class=\"row\"><span><strong style=\"color:var(--cream);font-size:1.0625rem;display:block\">Virtual staging</strong></span><b>$15 <small>/ photo</small></b></p>\n</div></section>\n\n<section class=\"wrap cta\"><h2 style=\"margin:0\">Ready to shoot?</h2><p>Pick your package and a time that works. You'll get a confirmation right away.</p><div class=\"acts\"><a class=\"btn\" href=\"/book\">Book a shoot</a><a class=\"btn btn--ghost\" href=\"/\">Back to the site</a></div></section>\n</main>\n<footer class=\"wrap\">&copy; Faith Vision Media &middot; Buffalo, NY</footer>\n</body></html>";
